mod solution;

fn main() {
    let cases = [
    (r#"[4,5,2,10,8]"#, r#"-1,4,-1,2,2"#),
    (r#"[2,1,3]"#, r#"-1,-1,1"#),
    (r#"
[2,1,3]
"#, r#"-1,-1,1"#),
    (r#"  
[4,5,2,10,8]
  "#, r#"-1,4,-1,2,2"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS monotonic-increasing-stack");
}
